mapper.insert:
/* insertGuildMemberActivityLog */
INSERT INTO guild_member_activity_log (
	guild_id
	,user_id
	,action_type
	,reference_id
	,summary
	,detail_json
) VALUES (
	CAST(#{guild_id} AS BIGINT)
	,#{user_id}
	,#{action_type}
	,#{reference_id}
	,#{summary}
	,CAST(#{detail_json} AS jsonb)
)

mapper.select:
/* countGuildMemberActivityLog */
SELECT COUNT(1)
  FROM guild_member_activity_log l
 WHERE l.guild_id = CAST(#{guild_id} AS BIGINT)

   AND l.user_id = #{user_id}


   AND l.action_type = #{action_type}

/* selectGuildMemberActivityLogList */ SELECT l.log_id ,l.guild_id ,l.user_id ,tu.user_nm AS user_name ,l.action_type ,l.reference_id ,l.summary ,l.detail_json ,l.crt_date FROM guild_member_activity_log l LEFT JOIN sys_user tu ON tu.user_id = l.user_id WHERE l.guild_id = CAST(#{guild_id} AS BIGINT)
AND l.user_id = #{user_id}
AND l.action_type = #{action_type}
ORDER BY l.crt_date DESC, l.log_id DESC LIMIT CAST(#{limit} AS INTEGER) OFFSET CAST(#{offset} AS INTEGER)

/* selectMonsterKrNamesByIds */ SELECT m.monster_id ,m.kr_name FROM monster m WHERE m.monster_id IN
#{id}
LIMIT 200
